public class Field {

	private static final Random rand = Randomizer.getRandom();

	private final int depth;
	private final int width;
	private final Cell[][] cells;


	public Field(int depth, int width) {
		this.depth = depth;
		this.width = width;
		cells = new Cell[depth][width];
		for (int row = 0; row < depth; row++) {
			for (int col = 0; col < width; col++) {
				cells[row][col] = new Cell();
			}
		}
	}


	public void clear() {
		for (int row = 0; row < depth; row++) {
			for (int col = 0; col < width; col++) {
				cells[row][col].clear();
			}
		}
	}


	public void clear(Movable movable, Location location) {
		cellAt(location).clear(movable.getOccupancyLayer());
	}


	public void place(Movable movable, int row, int col) {
		place(movable, new Location(row, col));
	}


	public void place(Movable movable, Location location) {
		cellAt(location).set(movable);
	}


	public void move(Movable movable, Location from, Location to) {
		if (from != null) {
			clear(movable, from);
		}
		if (to != null) {
			place(movable, to);
		}
	}


